def _define_hyperparameters():
    """Define hyperparameters for the MoE model with 4 experts."""
    return {
        'learning_rate': 0.001,
        'hidden_size': 128,
        'dropout_rate': 0.1,
        'neuron_embedding_dim': 8,
        'num_experts': 4 # Changed from 8 to 4
    }

def create_network(hparams: Dict[str, Any]):
    """Create and return the network with the MoE architecture."""
    return FullModelWrapper(hparams)
